// A thunk action creator returns a function
const fetchUser = (userId) => {
  // This function is the thunk
  return async (dispatch, getState) => {
    // 1. Dispatch loading state
    dispatch({ type: 'FETCH_USER_START' });

    try {
      // 2. Perform async operation
      const response = await fetch(`/api/users/${userId}`);

      if (!response.ok) {
        throw new Error('User not found');
      }

      const user = await response.json();

      // 3. Dispatch success with data
      dispatch({ type: 'FETCH_USER_SUCCESS', payload: user });
    } catch (error) {
      // 4. Dispatch error
      dispatch({ type: 'FETCH_USER_ERROR', payload: error.message });
    }
  };
};

// Usage - dispatch the thunk like any action
store.dispatch(fetchUser(123));

import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';

// createAsyncThunk handles the action lifecycle
// automatically dispatches: pending, fulfilled, rejected
export const fetchUserById = createAsyncThunk(
  'users/fetchById',
  async (userId, { rejectWithValue }) => {
    try {
      const response = await fetch(`/api/users/${userId}`);
      if (!response.ok) {
        throw new Error('Failed to fetch');
      }
      return await response.json();
    } catch (error) {
      return rejectWithValue(error.message);
    }
  }
);

const usersSlice = createSlice({
  name: 'users',
  initialState: { entities: {}, loading: 'idle', error: null },
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchUserById.pending, (state) => {
        state.loading = 'pending';
      })
      .addCase(fetchUserById.fulfilled, (state, action) => {
        state.loading = 'succeeded';
        state.entities[action.payload.id] = action.payload;
      })
      .addCase(fetchUserById.rejected, (state, action) => {
        state.loading = 'failed';
        state.error = action.payload;
      });
  },
});

// Usage in component
function UserProfile({ userId }) {
  const dispatch = useDispatch();
  const user = useSelector((state) => state.users.entities[userId]);
  const loading = useSelector((state) => state.users.loading);

  useEffect(() => {
    dispatch(fetchUserById(userId));
  }, [dispatch, userId]);

  if (loading === 'pending') return <Spinner />;
  if (loading === 'failed') return <Error />;
  return <div>{user?.name}</div>;
}

// Only fetch if data is stale (conditional dispatch)
const fetchUsersIfNeeded = () => {
  return (dispatch, getState) => {
    const { users } = getState();

    // Check if we should skip the fetch
    if (users.lastFetched && 
        Date.now() - users.lastFetched < 5 * 60 * 1000) {
      console.log('Data is fresh, skipping fetch');
      return;
    }

    // Check if already loading
    if (users.loading === 'pending') {
      console.log('Already fetching...');
      return;
    }

    // Proceed with fetch
    dispatch(fetchUsers());
  };
};

// Sequential operations with thunks
const processOrder = (orderId) => {
  return async (dispatch, getState) => {
    dispatch({ type: 'ORDER_PROCESSING', payload: orderId });

    // Wait for payment
    await dispatch(processPayment(orderId));

    // Check payment succeeded
    const { order } = getState();
    if (order.paymentStatus !== 'paid') {
      return dispatch({ type: 'ORDER_FAILED', payload: 'Payment failed' });
    }

    // Continue with fulfillment
    await dispatch(fulfillOrder(orderId));
    dispatch({ type: 'ORDER_COMPLETE', payload: orderId });
  };
};
